('A102-R2','R102-02','CN0375','historical_wastewater_2024','screening',1,'降低高盐/含氨处理负荷','先核既有吹脱/沉淀/蒸发与OAO的接口及模板剂组分；按分股盐度评估NF/RO或ED预浓缩，保留现行处理','conditional','盐、有机胺及结垢相容性；浓液合规去向和全成本','S102-04','INFERRED；历史设施不代表现行','各股实际来水、前后连接、浓缩物/冷凝水去向、膜及实际费用','分股采样、离子/有机物衡算、膜小试及现有设备经济性比较','维持既有工艺并优化',NULL,NULL,NULL,NULL,NULL,NULL,'缺六维实证','2026-11-28'),
