INSERT INTO evidence_notes(note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES
('N102-01','CN0373','S102-01','历史污水RO及浓水去向','安全生产与环保 美邦中科表','2024年度全厂生产及生活水共享站综合处理后清水回用，RO浓水纳低碳园区污水厂；废渗透膜来源污水处理站RO、污泥亦污水站，均资质单位处置。碳酸钠车间废过滤膜为另一范围。不证明2026实际流量、催化剂专线或全厂零排放。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N102-02','CN0373','S102-02','历史环评批准','环保合规表','公司2023问询函列乌环审〔2022〕24号混合项目正式环评批复，彼时拟建；非2024及2025验收。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N102-03','CN0374','S102-02','污泥和废树脂来源口径订正','8-1-1-159及注释','2023问询回复表明确污泥产生环节污水处理站，2019/2020/2021/2022年1–9月实际1.16/0.48/0.14/0.32t；2020/2021/2022年1–9月登记15/2/2t。废树脂表列THF生产，2019实际3.94t；后续101招股书提THF及污水站，保留范围差异。N101-07曾将污泥描述为THF生产污泥，本次更直接表证纠正，原笔记保留；2022前9月与全年口径不可互换。截图超限，正文可读。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N102-04','CN0374','S102-02','历史验收及排污许可更新','环保验收表；8-1-1-160注2','300t/a纳米钛硅项目批复银审服（环）函发〔2017〕139号，问询函列竣工验收文件，2021-12更新排污许可证，2022年前9月已投产。仍以2025停产及2026拟清算为当前阶段。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N102-05','CN0375','S102-05','独立厂区身份','1-1-32–35','2012-06-08成立，洪泽盐化工区盐都路北侧、洪盐路东侧；2024公开转让说明书列神马催化全资子公司，水合、钛硅等分子筛及委托加工，与河南神马新材料为不同物理基地。截图超时，正文可读。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N102-06','CN0375','S102-04','历史设施与许可','第19网页','公司回复列OAO280t/d、氨氮吹脱100t/d、三效2m³/h，均正常运行；废盐和污泥等危废第三方处置、危废暂存间原表60m³（非废水池）。许可913208295969864204001Q，2019-08-02至2022-08-01、2022-07-27至2027-07-26为报告列示期；最新变更待核。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N102-07','CN0375','S102-03','项目审批验收及不新增产能','第18网页表；S102-07法律意见书索引','2012淮环发297号5000t/a一期2500t/a，2015-04-07验收；2018淮环发278号技改、2020淮园环表复32号污泥干化，法律意见书称均2020-11-20自主验收；技改不新增能力（同回复第19网页）。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N102-08','CN0375','S102-06','近期监管列名','消防抽查名单','2026年9/10月政府消防监管名单列名，不证明实际产量或现行污水站运行。','WEB_PRIMARY','WEB_TEXT','2026-11-28'),
('N102-09','CN0144','S102-03','历史OAO及蒸发设施','第18网页催化新材料设施表','2024回复列好氧300t/d、厌氧500t/d、接触氧化500t/d，高效沉淀+蒸发浓缩1m³/h，均正常运行；污泥、脱水废盐、含铬钒预处理沉淀、四丙基溴化铵阳极液残留等资质处置。2026另有400m³/d站，尚不判为同一改造。历史摘要三效2m³/h未有该厂直接支持，本次不归入该厂，江苏黄马明确为2m³/h。','WEB_COMPANY','WEB_TEXT','2026-11-28'),
('N102-10','CN0144','S102-04','集团环保费用（非单厂）','第19网页（三）','2023/2022集团环保设备采购173.85/175.49万元、排污费118.24/89.44万元、污水处理费105.97/104.64万元、危废处理费31.26/89.81万元，合计429.32/459.39万元。含多子公司，不能赋给河南或淮安厂，不能除以集团用水量算吨水费。仅笔记留存；原回复集团用水9.15/9.83万吨非处理量。母公司不具体生产，子公司新许可原表字符91410422MA481R6GXCO01T疑OCR O/0，不填未经核实编号。','WEB_COMPANY','WEB_TEXT','2026-11-28');
